-- 056. Виктор, Алия, Ерлан, Тамара, Зоя, Роза-апа: тексты под озвучку (проверка voice-checker 25.11).
-- Без сокращений, омографов, «-ака», немецких вставок; время словами. Только текст; audio_url и условия сохраняются.
begin;
-- viktor
update characters set fixed_questions = jsonb_set(fixed_questions, '{0,a}', to_jsonb('"— Валентина Петровна в воскресенье с утра набирает: Витя, съезди, проверь дом. Ну, я поехал. Без двадцати десять был.\nВорота гаража закрыты. Тихо. Открываю — а он за рулём сидит.\nБак пустой. Мотор холодный, я рукой трогал. Ну и всё... Я к соседям, от них милицию вызвал. Больше ничего не трогал. Честно."'::json #>> '{}')) where id = '54b23338-3cf2-5d0a-99c4-91c0de226522';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R04' then jsonb_set(r, '{text}', to_jsonb('"Виктор мнёт кепку. Смотрит не на протокол, а на гараж.\n— Угорел, написали... (пауза)\nЯ вам так скажу. По четвергам он меня в пять отпускал. Всегда. «Витя, свободен, я сам». И сюда, на Кок-Тобе. Один. Это после развода так стало.\nДа каждый знал. Офис, на проходной ребята. Кто угодно.\n(пауза) И вот ещё. В позапрошлый четверг. Четырнадцатого. Выезжаю с базы — у ворот «Волга». Двадцать четвёртая, белая. Левая фара разбита, не горит.\nМужик за рулём сидит, курит. На ворота смотрит.\nНомер не запомнил, темно было. А фару запомнил. Я машины лучше людей помню."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '54b23338-3cf2-5d0a-99c4-91c0de226522';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R308' then jsonb_set(r, '{text}', to_jsonb('"Виктор перестаёт мять кепку.\n— В пятницу пустой? — Пауза. — А в воскресенье я приехал — машина внутри. Ворота закрыты.\n— Это что ж, её после кто-то пригнал?"'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '54b23338-3cf2-5d0a-99c4-91c0de226522';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R45' then jsonb_set(r, '{text}', to_jsonb('"Виктор стоит у ворот гаража. Внутрь не заходит.\n— Я у него полтора года водителем был. Каждый день.\nКроме четверга. В пять — «свободен, Витя». И сам за руль. И сюда, наверх. Один.\nПосле развода так стало. На базе каждый знал. На проходной ему шлагбаум заранее поднимали.\n(пауза) А ещё... В позапрошлый четверг, четырнадцатого, у ворот базы «Волга» стояла. Белая, двадцать четвёртая. Левая фара разбита.\nМужик сидит, курит. На ворота смотрит.\nЯ тогда подумал — клиента ждёт. Ну, частник. А теперь не знаю, что и думать."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '54b23338-3cf2-5d0a-99c4-91c0de226522';
-- aliya
update characters set intro_text = replace(intro_text, 'Участковый в семь утра в дверь звонил.', 'Участковый в семь утра в дверь стучал.') where id = '96e916c8-7fd0-5edc-a4fe-1a6aeda231bf';
update characters set fixed_questions = jsonb_set(fixed_questions, '{1,a}', to_jsonb('"— Ссорились. На прошлой неделе, у его матери. Я крикнула: «Чтоб ты сдох с этим домом». Валентина Петровна вам доложила. Или доложит.\nДом строили на деньги от квартиры моих родителей. А записал он его на себя.\n(пауза) Вот и весь мой мотив. Записывайте."'::json #>> '{}')) where id = '96e916c8-7fd0-5edc-a4fe-1a6aeda231bf';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R06' then jsonb_set(r, '{text}', to_jsonb('"Алия смотрит на снимок следа. Коротко смеётся. Зло.\n— Тридцать седьмой. Мой.\nЛадно. Была.\nВ пятницу. В три часа дня. Специально выбрала, когда он на работе.\nКлючи старые, на одной связке остались. И подошли: он ничего не менял. Жадность.\nЗабрала папку о приватизации. Для адвоката, для иска.\n(пауза) Гараж был пустой. Машины не было. Никого не было.\nА в субботу — с восьми вечера до восьми утра дежурство. В десять минут двенадцатого я давала наркоз, экстренная. Журнал дежурств, протокол с моей подписью.\nПроверяйте.\nЯ его хотела засудить. Не убить."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '96e916c8-7fd0-5edc-a4fe-1a6aeda231bf';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R116' then jsonb_set(r, '{text}', to_jsonb('"Алия читает быстро. Профессионально. Сначала выводы.\n— Механическая асфиксия. Окиси углерода нет. В машину посадили мёртвым.\n(пауза)\n— Я ему десять лет говорила: угоришь. А его задушили. — Возвращает лист. — Под ногтями чужая кровь? У меня берите. Пожалуйста. Хоть сейчас."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '96e916c8-7fd0-5edc-a4fe-1a6aeda231bf';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R118' then jsonb_set(r, '{text}', to_jsonb('"Алия читает. На словах «Береги Дашу» лицо у неё белеет.\n— Он назвал мою дочь. По имени.\n(пауза)\n— Фархад. Даша у него на коленях сидела. — Голос садится. — Где он сейчас? Скажите мне, где он сейчас."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '96e916c8-7fd0-5edc-a4fe-1a6aeda231bf';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R205' then jsonb_set(r, '{text}', to_jsonb('"Алия дочитывает. Губы белые.\n— Фархад. Своими руками. — Пауза. — Даше я скажу сама. Не вы."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '96e916c8-7fd0-5edc-a4fe-1a6aeda231bf';
-- erlan
update characters set fixed_questions = jsonb_set(fixed_questions, '{0,a}', to_jsonb('"— Находился на посту. С восьми вечера до восьми утра, смена.\nЗвонок на пульт агентства — каждый час. Журнал смены у старшего.\nПроверяйте. Я бы сам проверил, братан. Ну, на вашем месте."'::json #>> '{}')) where id = '2d9e7245-2e05-5079-86f1-f9b2edb1f3e9';
update characters set fixed_questions = jsonb_set(fixed_questions, '{1,a}', to_jsonb('"— Да каждый знал. Проходная, офис, грузчики.\nОн в пять водилу отпускал — и сам за руль. Тайна, тоже мне."'::json #>> '{}')) where id = '2d9e7245-2e05-5079-86f1-f9b2edb1f3e9';
update characters set fixed_questions = jsonb_set(fixed_questions, '{3,a}', to_jsonb('"— А ты знаешь, как бывшие менты сидят? Вот.\nЯ думал: разговор у них. Мужской.\nА тут его нашли. И я себе сказал: угорел. Угорел, и всё. (тушит сигарету мимо пепельницы) Так легче было."'::json #>> '{}')) where id = '2d9e7245-2e05-5079-86f1-f9b2edb1f3e9';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R21' then jsonb_set(r, '{text}', to_jsonb('"Ерлан читает листок. Пепел с сигареты падает на колено.\n— Да чё ты... Ладно. Ладно, братан.\nФархад. Три года назад мать на операцию легла. Надо было полторы тысячи долларов. Он дал. Без расписки.\nЯ не вернул. Меня из милиции попёрли — какие деньги.\nА за две недели до всего — в субботу, девятого — в чайхане у Зелёного он мне говорит: забудь долг. Только скажи, когда Игорь один ездит. Поговорить, мол, по-мужски. Без водилы.\nНу я и сказал: по четвергам.\nВ четверг он мне на пейджер: «в силе?». Я набрал. В силе.\nВсё. Думал — разговор.\nВ субботу находился на посту, с восьми вечера до восьми утра, звонок на пульт каждый час.\n(трёт колено) А когда Игоря нашли... гнал от себя. Молчал."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '2d9e7245-2e05-5079-86f1-f9b2edb1f3e9';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R22' then jsonb_set(r, '{text}', to_jsonb('"Ерлан слушает выдержку из показаний. Тушит сигарету о край стола, мимо пепельницы.\n— Сдал, значит, Фархад. Ну да.\nБыло. Три года назад он мне полторы тысячи дал. На операцию матери. Я не вернул.\nА девятого, в субботу, в чайхане у Зелёного — недели за две до всего — говорит: спишу. Только скажи, когда Игорь без водилы ездит. Поговорить надо. По-мужски.\nЯ сказал: по четвергам.\nВ четверг на пейджер пришло: «в силе?». Я набрал, подтвердил.\nБольше ничего не знал, хоть режь. Думал — разговор.\nВ субботу на смене был. С восьми вечера до восьми утра, звонок на пульт каждый час. Проверяй."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '2d9e7245-2e05-5079-86f1-f9b2edb1f3e9';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R248' then jsonb_set(r, '{text}', to_jsonb('"— Сдал, значит, Фархад. Ну да. Я всё сказал, в протоколе есть. Больше ничего не знал, хоть режь."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '2d9e7245-2e05-5079-86f1-f9b2edb1f3e9';
-- tamara
update characters set intro_text = replace(intro_text, 'Ну, Gott sei Dank.', 'Ну, слава богу.') where id = '631694f6-0ec1-523d-9f2a-599f875223c1';
update characters set fixed_questions = jsonb_set(fixed_questions, '{0,a}', to_jsonb('"— Почти сорок лет, деточка. Дети мои в Германии третий год, в Кёльне. А я документы жду. Каждый месяц пишу, каждый месяц мне отвечают: ждите. Ну, ждите так ждите. Жду. — Поправляет платок. — Пенсию тут с задержкой дают. Там, говорят, вовремя. Из наших я на всю улицу одна осталась. Уехали. До единого."'::json #>> '{}')) where id = '631694f6-0ec1-523d-9f2a-599f875223c1';
update characters set fixed_questions = jsonb_set(fixed_questions, '{1,a}', to_jsonb('"— А что там разглядывать? Я его в лицо знаю. Он ко мне заходил, спрашивал, не надо ли кому дом. — Пауза. — Фара у «Волги» одна горела. Правая. А он прямо в свет вышел, к калитке. Это ещё до того было, как свет отключили. По радио новости как раз кончились. — Кивает на своё окно. — А после везде темно. Только у Шмидтов в окне керосинка. Я сама с керосинкой у окна сижу, когда света нет. У меня давление, я не сплю."'::json #>> '{}')) where id = '631694f6-0ec1-523d-9f2a-599f875223c1';
update characters set fixed_questions = jsonb_set(fixed_questions, '{2,a}', to_jsonb('"— А что я скажу? Что у соседей печку топят? Фархад сказал: люди въедут. Ну, я и думала — въехали. — Молчит. — И ещё… Милицию я боюсь, извините. С советского времени боюсь. Затаскают, и к детям не выпустят. Нет, думаю, не надо мне."'::json #>> '{}')) where id = '631694f6-0ec1-523d-9f2a-599f875223c1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R124' then jsonb_set(r, '{text}', to_jsonb('"— Покупателю? — Тамара Фёдоровна даже привстаёт. — Господи… Какой покупатель? Никакого покупателя не было!\n(поправляет платок)\n— Я у окна сидела. С керосинкой. Двое вышли, он и парень. Парень ушёл пешком. И всё. Больше никто не приезжал, ни одна машина. Я бы слышала, деточка, у нас тут машин нету.\n— Вы ему так и скажите. Что Тамара не спала."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '631694f6-0ec1-523d-9f2a-599f875223c1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R125' then jsonb_set(r, '{text}', to_jsonb('"— При свечке? Дома? — Тамара Фёдоровна качает головой. — Ну да. Свечка, может, и была. Только не у него дома.\n(пауза)\n— «Волга» его у калитки стояла. До ночи. Я ещё думала: что ж он машину на улице бросил, разуют.\n— Я старая, но я не слепая. Так и запишите."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '631694f6-0ec1-523d-9f2a-599f875223c1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R18' then jsonb_set(r, '{text}', to_jsonb('"Тамара Фёдоровна у забора. Пальто поверх халата. Смотрит, как Сеитова поднимается из люка с пакетом.\n— Господи… Значит, был там кто-то. Был. — Прижимает руку к груди. — Я всё скажу. У меня давление, я не сплю, у окна сижу. Дом Фархад продаёт. Покупателей водил, я его в лицо знаю. В среду сказал: скоро люди въедут.\nВ пятницу смотрю — дым. Из трубы. Под навесом машина тёмная, не наша, иномарка. Парень печку топил. Высокий, молодой.\nА в субботу в четверть седьмого — «Волга» белая. Одна фара. Вышли двое: Фархад, прямо в свет, и тот парень. Парень скоро пешком ушёл. И всё. Никаких покупателей, никто больше не приезжал.\nПосле свет отключили. Везде темно, а у Шмидтов керосинка. До ночи. — Пауза. — В двадцать минут двенадцатого иномарка со двора выехала. Без фар. Я её по мотору узнала, у наших так не урчит. А «Волга» у калитки до половины второго стояла. По свежему снегу уехала."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '631694f6-0ec1-523d-9f2a-599f875223c1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R19' then jsonb_set(r, '{text}', to_jsonb('"Тамара Фёдоровна держит справку на вытянутой руке. Очки в другой комнате.\n— Шмидты… Хорошие люди. Весной уехали, к сыну. Мои тоже там. А я вот жду. Бумаги жду. — Пауза. — Дом Фархад продаёт. По доверенности. Покупателей водил, я его в лицо знаю. В среду говорит: скоро въедут люди. Ну, я и думала — въехали.\nВ пятницу из трубы дым. Под навесом машина тёмная. Не наша, иномарка. Печку парень топил. Высокий. Молодой.\nА в субботу… по радио как раз новости кончились. Четверть седьмого. «Волга» белая, одна фара горит. Вышли Фархад и тот парень. Парень скоро ушёл. Пешком. А покупателей не было. Ну да, кто ж в темноте дом смотрит?\nПосле свет отключили. У меня давление, я не сплю. На всей улице одно окно светилось. У Шмидтов. Керосинка.\nВ двадцать минут двенадцатого иномарка выехала. Без фар. Я по мотору узнала. А «Волга» стояла. До половины второго. Уехала по снегу, по свежему. — Господи… Я же думала — покупатели."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '631694f6-0ec1-523d-9f2a-599f875223c1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R86' then jsonb_set(r, '{text}', to_jsonb('"— Доверенность? Да, Шмидты ему оставили, когда уезжали. Дом продавать.\nКлючи тоже у него. Он и покупателей водил.\n(качает головой)\nА доллары... Ну да. Этого я не знаю."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '631694f6-0ec1-523d-9f2a-599f875223c1';
-- zoya
update characters set fixed_questions = jsonb_set(fixed_questions, '{1,a}', to_jsonb('"— Да кто только не ходит. Из школы её бывшие, родня, с его работы. Курящие, некурящие… я всех на балкон. — Кивает в сторону кухни. — А Фархад с утра здесь. Вот кто человек. И хлеба принёс, и Валентину Петровну под руку держит, не отходит. — Пауза. — Я не сплетничаю, я констатирую. У человека горе, а он тут."'::json #>> '{}')) where id = '753087d6-7c38-5bf7-889e-3c4477902369';
update characters set fixed_questions = jsonb_set(fixed_questions, '{2,a}', to_jsonb('"— Стены здесь толстые. Дом старый. Но я слышала. Что-то у неё стряслось: ходила, ходила… ночью не спала. — Мнёт полотенце. — Я не спросила. Думала, давление. У нас у всех давление. — Пауза. — Надо было спросить. Вы это не записывайте. Не записывайте, я прошу."'::json #>> '{}')) where id = '753087d6-7c38-5bf7-889e-3c4477902369';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R54' then jsonb_set(r, '{text}', to_jsonb('"Зоя Михайловна всё это время стоит в дверях кухни. Полотенце через плечо. Откашливается.\n— Я не сплетничаю. Я констатирую. Если Валентина Петровна говорит, что Данияр в субботу был здесь, — значит, был. «Девятка» его белая под моим окном стояла. С вечера и до глубокой ночи. Он её вечно колесом на газон ставит, я ему сто раз… — Машет рукой. — А около десяти, перед вторым «Временем», опять потянуло табаком. Я вышла на площадку. Он там. Курит. Заграничные. И окурки в банку у мусоропровода. Я ему говорю: молодой человек, тут люди живут."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '753087d6-7c38-5bf7-889e-3c4477902369';
-- roza
update characters set fixed_questions = jsonb_set(fixed_questions, '{0,a}', to_jsonb('"— Олжас? Тихий. Из аула. Техникум бросил, на базаре грузчиком. Матери деньги отправляет.\n(поправляет платок)\nНе пьёт, не дерётся. Таких бы больше."'::json #>> '{}')) where id = 'ad04679a-62fd-52ac-a043-6e04873ad6b3';
update characters set fixed_questions = jsonb_set(fixed_questions, '{1,a}', to_jsonb('"— А вот журнал. У меня каждый записан, кто вошёл, кто вышел.\n(разворачивает журнал к вам)\nПришёл в половине восьмого. Мокрый весь. И сразу наверх. Не выходил он: у меня с одиннадцати дверь заперта, ключ вот он.\nРебята в комнате скажут, они в карты до ночи играли. А он лежал. Лицом к стене."'::json #>> '{}')) where id = 'ad04679a-62fd-52ac-a043-6e04873ad6b3';
commit;
